if (ctx.url == null || ctx.url.domain == null) { return; }
String d = ctx.url.domain.toLowerCase();
for (String x : params.domains) {
  if (d.equals(x) || d.endsWith('.' + x)) {
    if (params.sanctioned.contains(x)) { return; }
    if (ctx.ai == null) { ctx.ai = new HashMap(); }
    if (ctx.ai.shadow == null) { ctx.ai.shadow = new HashMap(); }
    ctx.ai.shadow.detected = true;
    ctx.ai.shadow.service = x;
    return;
  }
}
